class WorkflowCatalog:
    def __init__(self):
        self._steps = {}

    def add(self, name, action, requires=(), description=""):
        if not isinstance(name, str):
            raise TypeError("name must be a string")
        if not name:
            raise ValueError("name cannot be empty")
        if not callable(action):
            raise TypeError("action must be callable")
        if not isinstance(description, str):
            raise TypeError("description must be a string")
        try:
            dependencies = tuple(requires)
        except TypeError as exc:
            raise TypeError("requires must be iterable") from exc
        if any(not isinstance(item, str) for item in dependencies):
            raise TypeError("prerequisite names must be strings")
        if any(not item for item in dependencies):
            raise ValueError("prerequisite names cannot be empty")
        if len(set(dependencies)) != len(dependencies):
            raise ValueError("prerequisites must be distinct")
        if name in self._steps:
            raise KeyError(name)
        self._steps[name] = (action, dependencies, description)

    def run(self, name):
        if not isinstance(name, str):
            raise TypeError("name must be a string")
        results = []
        completed = set()
        active = set()

        def visit(current):
            if current in completed:
                return
            if current in active:
                raise ValueError("workflow contains a cycle")
            if current not in self._steps:
                raise KeyError(current)
            active.add(current)
            action, dependencies, _ = self._steps[current]
            for dependency in reversed(dependencies):
                visit(dependency)
            active.remove(current)
            completed.add(current)
            results.append((current, action()))

        visit(name)
        return results

    def describe(self):
        return [
            (name, description, tuple(dependencies))
            for name, (_, dependencies, description) in self._steps.items()
        ]

